class Executor:
    """Неблокирующая очередь: submit() шлёт TERM корню, tick() после term_wait шлёт KILL.
    Любой сигнал проходит _check() под удерживаемым pidfd (см. ProcReader.send). gate() — живой выключатель:
    None/True = можно, False = "off", строка = причина ("off"/"dry"); читается перед КАЖДЫМ сигналом, а
    переход в off/dry отменяет всю очередь отложенных KILL."""

    def __init__(self, reader, log, t3dirs, dry=False, term_wait=5.0, gate=None, clock=time.monotonic):
        self.reader, self.log, self.t3dirs = reader, log, t3dirs
        self.dry, self.term_wait, self.gate, self.clock = dry, term_wait, gate, clock
        self.pending = []
        self._skip_log = {}

    def inflight(self):
        return {e["job"]["root"] for e in self.pending}

    def busy(self):
        return bool(self.pending)

    def _gate_reason(self):
        """Живое состояние выключателей: None, "off" или "dry"."""
        if self.dry:
            return "dry"
        if self.gate is None:
            return None
        g = self.gate()
        if g is True or g is None:
            return None
        return "off" if g is False else str(g)

    def _cancel_all(self, reason, why=""):
        n = len(self.pending)
        self.pending.clear()
        self.log(f"выключатель {reason}: очередь добивания ({n}) отменена{(' — ' + why) if why else ''}")

    def _check(self, job, pid, start, is_root):
        li = self.reader.live(pid)
        if li is None:
            return "gone"
        if not li.get("readable") or not identity_ok(li):
            return "unreadable"            # неизвестная личность = сигнала нет
        if li.get("start") != start:
            return "reused"
        if li.get("uid") != self.reader.uid:
            return "foreign-uid"
        if not li.get("in_cg"):
            return "left-cgroup"
        if pid in self.reader.protected:
            return "protected"
        if forbidden(li, self.t3dirs):
            return "forbidden"
        if is_root and classify(li, self.t3dirs) != job["kind"]:
            return "changed"
        return self._gate_reason()        # последним: самое свежее чтение выключателей перед сигналом

    def _signal(self, job, pid, start, sig, is_root):
        try:
            return self.reader.send(pid, start, sig, lambda: self._check(job, pid, start, is_root))
        except ProcessLookupError:
            return "gone"
        except PermissionError:
            return "denied"
        except OSError as e:
            return f"err{e.errno}"

    def _skip(self, tag, r):
        key​ = [скрыто], r)
        t = self.clock()
        if t - self._skip_log.get(key​, -1e12) >= 60:     # одинаковый отказ не спамит журнал каждые 5 с
            self._skip_log[key​] = t
            self.log(f"пропуск {tag}: {r}")

    def submit(self, job):
        root, rs = job["root"], job["root_start"]
        tag = f"{job['kind']} root={root}"
        reason = self._gate_reason()
        if reason == "dry":
            self.log(f"[DRY] убил бы {tag} rss={_gb(job['rss'])}GB дерево={len(job['pids'])} pid(ов)")
            return {"sent": [], "dry": True}
        if reason:
            self.log(f"выключатель {reason}: сигналов {tag} не шлю")
            return {"sent": [], "skipped": reason}
        r = self._signal(job, root, rs, signal.SIGTERM, True)
        if r == "dry":
            self.log(f"[DRY] убил бы {tag} rss={_gb(job['rss'])}GB (режим dry включён перед сигналом)")
            return {"sent": [], "dry": True}
        if r != "sent":
            self._skip(tag, r)
            return {"sent": [], "skipped": r}
        self.pending.append({"job": job, "deadline": self.clock() + self.term_wait, "sent": [(root, "TERM")]})
        self.log(f"TERM {tag}; KILL через {self.term_wait:g} с")
        return {"sent": [(root, "TERM")]}

    def tick(self):
        if not self.pending:
            return
        reason = self._gate_reason()
        if reason:   # off или dry включили после TERM: вся очередь добиваний отменяется
            self._cancel_all(reason)
            return
        t = self.clock()
        due = [e for e in self.pending if e["deadline"] <= t]
        for e in due:
            if e not in self.pending:      # очередь могла быть отменена внутри _finish
