def calc_reclaim(stat):
    """Консервативная оценка памяти, которую ядро вернёт само (кэш файлов), в байтах; None — неизвестно.
    reclaimable = max(inactive_file, file - shmem - unevictable - file_dirty - file_writeback).
    Если хоть одно вычитаемое поле отсутствует, второе слагаемое неизвестно и берётся только inactive_file.
    Нет inactive_file — оценки нет (R2 по оценке молчит)."""
    if "inactive_file" not in stat:
        return None
    inactive = stat["inactive_file"]
    need = ("file", "shmem", "unevictable", "file_dirty", "file_writeback")
    if any(k not in stat for k in need):
        return inactive
    return max(inactive, stat["file"] - stat["shmem"] - stat["unevictable"] - stat["file_dirty"]
               - stat["file_writeback"])


